await page.evaluate(async () => {
  const origin = location.origin;
  const robotsRes = await fetch(origin + '/robots.txt');
  const robotsOk = robotsRes.ok;
  const robotsText = robotsOk ? await robotsRes.text() : '';
  const sitemaps = robotsText.split(/\r?\n/).filter(l => /^\s*Sitemap:/i.test(l)).map(l => l.replace(/^\s*Sitemap:\s*/i, '').trim()).sort();
  const smRes = await fetch(origin + '/sitemap.xml');
  const smText = smRes.ok ? await smRes.text() : '';
  let locs = [];
  try { locs = [...new DOMParser().parseFromString(smText, 'application/xml').getElementsByTagName('loc')].map(e => e.textContent.trim()); } catch(e) {}
  const host = location.hostname;
  const allSameHost = locs.every(u => { try { return new URL(u).hostname === host; } catch(e) { return false; } });
  window.__bench_finding = { robotsPresent: robotsOk, robotsSitemaps: sitemaps, sitemapUrlCount: locs.length, allSameHost };
});

